.telegraph-word {
  align-items: center;
  background: #080a08;
  border: 1px solid rgba(217, 255, 241, 0.16);
  border-radius: 14px;
  color: #d9fff1;
  cursor: pointer;
  display: inline-grid;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  height: 112px;
  isolation: isolate;
  justify-content: center;
  min-width: min(100%, 430px);
  overflow: hidden;
  padding: 0 30px;
  position: relative;
  box-shadow:
    0 18px 42px rgba(0, 0, 0, 0.16),
    inset 0 1px rgba(255, 255, 255, 0.07);
}
.telegraph-word::before {
  background: repeating-linear-gradient(
    to bottom,
    rgba(255, 255, 255, 0.04) 0 1px,
    transparent 1px 7px
  );
  content: "";
  inset: 0;
  opacity: 0.36;
  pointer-events: none;
  position: absolute;
  z-index: 2;
}
.telegraph-word::after {
  background: linear-gradient(
    to right,
    transparent,
    rgba(43, 255, 184, 0.16),
    transparent
  );
  content: "";
  height: 100%;
  opacity: 0;
  pointer-events: none;
  position: absolute;
  top: 0;
  transform: translateX(-130%);
  width: 46%;
  z-index: 1;
}
.telegraph-word:hover,
.telegraph-word:focus-visible {
  border-color: rgba(43, 255, 184, 0.38);
}
.telegraph-word:hover::after,
.telegraph-word:focus-visible::after {
  animation: telegraph-sweep 1.2s linear infinite;
  opacity: 1;
}
.telegraph-word:focus-visible {
  outline: 2px solid #ffce5c;
  outline-offset: 4px;
}
.telegraph-word-grid {
  background-image:
    linear-gradient(rgba(43, 255, 184, 0.07) 1px, transparent 1px),
    linear-gradient(90deg, rgba(43, 255, 184, 0.07) 1px, transparent 1px);
  background-size: 22px 22px;
  inset: 0;
  opacity: 0.36;
  pointer-events: none;
  position: absolute;
  z-index: 0;
}
.telegraph-word-text {
  display: block;
  font-size: clamp(14px, 3vw, 25px);
  font-weight: 760;
  letter-spacing: 0;
  line-height: 1;
  max-width: 100%;
  position: relative;
  text-align: center;
  text-shadow: 0 0 16px rgba(43, 255, 184, 0.34);
  white-space: pre-wrap;
  overflow-wrap: anywhere;
  z-index: 3;
}
.telegraph-word--rainbow {
  background: light-dark(#fff, #24292e);
  border-color: light-dark(rgba(0, 0, 0, 0.08), rgba(255, 255, 255, 0.12));
  color: light-dark(#111, #f3f5f6);
  box-shadow:
    0 16px 38px rgba(20, 24, 40, 0.08),
    inset 0 0 0 1px
      light-dark(rgba(255, 255, 255, 0.9), rgba(255, 255, 255, 0.05));
  font-family:
    "PingFang SC",
    "PingFang TC",
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}
.telegraph-word--rainbow::before,
.telegraph-word--rainbow::after {
  display: none;
}
.telegraph-word--rainbow:hover,
.telegraph-word--rainbow:focus-visible {
  border-color: light-dark(rgba(0, 0, 0, 0.14), rgba(255, 255, 255, 0.22));
}
.telegraph-word--rainbow .telegraph-word-grid {
  display: none;
}
.telegraph-word--rainbow .telegraph-word-text {
  color: light-dark(#111, #f3f5f6);
  font-weight: 820;
  text-shadow: none;
}
.telegraph-word--rainbow[data-target="expanded"] .telegraph-word-text {
  font-weight: 540;
}
.telegraph-word--rainbow:hover .telegraph-word-text,
.telegraph-word--rainbow:focus-visible .telegraph-word-text {
  animation: telegraph-rainbow-sweep 4.2s linear infinite;
  background: linear-gradient(
    105deg,
    light-dark(#111, #f3f5f6) 0 32%,
    #ff2f55 40%,
    #ffb000 47%,
    #25c05a 54%,
    #00a3ff 61%,
    #7c4dff 68%,
    #ff2fb3 75%,
    light-dark(#111, #f3f5f6) 84%
  );
  background-clip: text;
  background-size: 260% 100%;
  color: transparent;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
@keyframes telegraph-sweep {
  to {
    transform: translateX(250%);
  }
}
@keyframes telegraph-rainbow-sweep {
  from {
    background-position: 125% 50%;
  }
  to {
    background-position: -125% 50%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .telegraph-word::after,
  .telegraph-word-text {
    animation: none !important;
  }
}

"use client";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { cn } from "@/lib/utils";
import {
  makeTelegraphTransitionPlan,
  renderTelegraphTransitionFrame,
  telegraphDuration,
} from "@/lib/telegraph-engine";
import "./telegraph-text.css";

export type TelegraphTextProps = ComponentProps<"button"> & {
  text: string;
  expandedText: string;
  variant?: "dark" | "rainbow";
  frameDuration?: number;
};

export function TelegraphText({
  text,
  expandedText,
  variant = "dark",
  frameDuration = 26,
  className,
  onMouseEnter,
  onMouseLeave,
  onFocus,
  onBlur,
  onClick,
  ...props
}: TelegraphTextProps) {
  const readout = useRef<HTMLSpanElement>(null);
  const current = useRef(text);
  const seed = useRef(3);
  const [expanded, setExpanded] = useState(false);
  const target = expanded ? expandedText : text;
  useEffect(() => {
    const node = readout.current;
    if (!node) return;
    const from = current.current;
    const plan = makeTelegraphTransitionPlan(from, target, {
      seed: seed.current++,
    });
    const duration = telegraphDuration(plan);
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    let raf = 0;
    let started: number | undefined;
    const finish = () => {
      cancelAnimationFrame(raf);
      node.textContent = target;
      current.current = target;
    };
    const tick = (now: number) => {
      started ??= now;
      const frame = Math.min(
        duration,
        Math.floor((now - started) / Math.max(1, frameDuration)),
      );
      current.current = renderTelegraphTransitionFrame(
        from,
        target,
        frame,
        plan,
      );
      node.textContent = current.current;
      if (frame < duration) raf = requestAnimationFrame(tick);
    };
    if (media.matches || from === target) finish();
    else raf = requestAnimationFrame(tick);
    const onPreference = () => {
      if (media.matches) finish();
    };
    media.addEventListener("change", onPreference);
    return () => {
      cancelAnimationFrame(raf);
      media.removeEventListener("change", onPreference);
    };
  }, [target, frameDuration]);
  return (
    <button
      type="button"
      {...props}
      data-slot="telegraph-text"
      data-target={expanded ? "expanded" : "compact"}
      className={cn("telegraph-word", `telegraph-word--${variant}`, className)}
      aria-label={target}
      aria-expanded={expanded}
      onMouseEnter={(e) => {
        onMouseEnter?.(e);
        if (
          !e.defaultPrevented &&
          !props.disabled &&
          matchMedia("(hover: hover)").matches
        )
          setExpanded(true);
      }}
      onMouseLeave={(e) => {
        onMouseLeave?.(e);
        if (!e.defaultPrevented) setExpanded(false);
      }}
      onFocus={(e) => {
        onFocus?.(e);
        if (!e.defaultPrevented && !matchMedia("(pointer: coarse)").matches)
          setExpanded(true);
      }}
      onBlur={(e) => {
        onBlur?.(e);
        if (!e.defaultPrevented) setExpanded(false);
      }}
      onClick={(e) => {
        onClick?.(e);
        if (!e.defaultPrevented) setExpanded((value) => !value);
      }}
    >
      <span className="telegraph-word-grid" aria-hidden="true" />
      <span className="telegraph-word-text" ref={readout} aria-hidden="true">
        {text}
      </span>
    </button>
  );
}

export type TelegraphPlan = {
  char: string;
  from?: string;
  start: number;
  end: number;
  salt: number;
  static: boolean;
}[];
export const TELEGRAPH_GLYPHS =
  "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789<>/[]{}#+-=*";

function seededInt(seed: number, index: number, max: number) {
  const x = Math.sin((seed + 1) * 97.13 + (index + 1) * 43.71) * 10000;
  return Math.floor((x - Math.floor(x)) * max);
}

export function makeTelegraphPlan(text: string, { seed = 0 } = {}) {
  let cursor = 0;

  return [...String(text)].map((char, index) => {
    if (/\s/.test(char)) {
      return { char, start: 0, end: 0, salt: index + seed, static: true };
    }

    const start = cursor + seededInt(seed, index, 3);
    const hold = 8 + seededInt(seed + 17, index, 10);
    cursor = start + 2;

    return {
      char,
      start,
      end: start + hold,
      salt: seed * 31 + index * 17,
      static: false,
    };
  });
}

export function makeTelegraphTransitionPlan(
  from: string,
  to: string,
  { seed = 0 } = {},
) {
  const fromChars = [...String(from)];
  const toChars = [...String(to)];
  const length = Math.max(fromChars.length, toChars.length);
  let cursor = 0;

  return Array.from({ length }, (_, index) => {
    const fromChar = fromChars[index] ?? " ";
    const toChar = toChars[index] ?? "";
    if (fromChar === toChar) {
      return {
        char: toChar,
        from: fromChar,
        start: 0,
        end: 0,
        salt: index + seed,
        static: true,
      };
    }
    if (/\s/.test(fromChar) && /\s/.test(toChar || " ")) {
      return {
        char: toChar,
        from: fromChar,
        start: 0,
        end: 0,
        salt: index + seed,
        static: true,
      };
    }

    const start = cursor + seededInt(seed + 23, index, 3);
    const hold = 6 + seededInt(seed + 41, index, 8);
    cursor = start + 1;

    return {
      char: toChar,
      from: fromChar,
      start,
      end: start + hold,
      salt: seed * 31 + index * 17,
      static: false,
    };
  });
}

export function telegraphDuration(plan: TelegraphPlan) {
  return Math.max(0, ...plan.map((item) => item.end)) + 1;
}

export function renderTelegraphFrame(
  text: string,
  frame: number,
  plan = makeTelegraphPlan(text),
  glyphs = TELEGRAPH_GLYPHS,
) {
  return [...String(text)]
    .map((char, index) => {
      const item = plan[index];
      if (!item || item.static || /\s/.test(char)) return char;
      if (frame < item.start) return " ";
      if (frame >= item.end) return char;

      const glyphIndex = Math.abs(
        (frame * 13 + item.salt * 7 + index * 19) % glyphs.length,
      );
      return glyphs[glyphIndex];
    })
    .join("");
}

export function renderTelegraphTransitionFrame(
  from: string,
  to: string,
  frame: number,
  plan = makeTelegraphTransitionPlan(from, to),
  glyphs = TELEGRAPH_GLYPHS,
) {
  const duration = telegraphDuration(plan);
  if (frame >= duration) return String(to);

  return plan
    .map((item, index) => {
      if (item.static) return item.char;
      if (frame < item.start) return item.from;
      if (frame >= item.end) return item.char;

      const glyphIndex = Math.abs(
        (frame * 13 + item.salt * 7 + index * 19) % glyphs.length,
      );
      return glyphs[glyphIndex];
    })
    .join("")
    .trimEnd();
}

import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}
